function agruparPorFaixa(pedidos) {
  const faixas = { 'ate-50': 0, '50-200': 0, '200-500': 0, 'acima-500': 0 }

  for (const pedido of pedidos) {
    const valor = pedido?.valor
    if (!Number.isFinite(valor)) continue

    if (valor < 50) faixas['ate-50'] += 1
    else if (valor < 200) faixas['50-200'] += 1
    else if (valor < 500) faixas['200-500'] += 1
    else faixas['acima-500'] += 1
  }

  return faixas
}

