function paginarPorCursor(registros, cursor, limite) {
  const tamanho = Math.min(Math.max(1, limite || 20), 100)

  let inicio = 0
  if (cursor !== null && cursor !== undefined) {
    const posicao = registros.findIndex((registro) => registro.id === cursor)
    if (posicao === -1) return { itens: [], proximoCursor: null }
    inicio = posicao + 1
  }

  const itens = registros.slice(inicio, inicio + tamanho)
  const temMais = inicio + tamanho < registros.length

  return {
    itens,
    proximoCursor: temMais && itens.length > 0 ? itens[itens.length - 1].id : null,
  }
}

const SENSIVEIS = new Set(['senha', 'password', 'token', 'authorization', 'apikey', 'secret', 'cpf'])

function mascarar(valor) {
  if (Array.isArray(valor)) {
    return valor.map((item) => mascarar(item))
  }

  if (valor === null || typeof valor !== 'object') {
    return valor
  }

  const saida = {}
  for (const [chave, conteudo] of Object.entries(valor)) {
    saida[chave] = SENSIVEIS.has(chave.toLowerCase()) ? '***' : mascarar(conteudo)
  }
  return saida
}

function mesclarErros(valores, erros) {
  const mapa = {}
  for (const erro of erros ?? []) {
    if (erro?.campo) mapa[erro.campo] = erro.mensagem
  }

  const ordem = Object.keys(valores ?? {})
  const primeiro = ordem.find((campo) => campo in mapa) ?? null

  return {
    valores: { ...valores },
    erros: mapa,
    primeiroCampoComErro: primeiro,
  }
}

function planejarTentativas(statusSequencia, maxTentativas) {
  const esperas = []
  let tentativas = 0

  for (let indice = 0; indice < maxTentativas; indice += 1) {
    const status = statusSequencia[indice]
    tentativas += 1

    const transitorio = status === 'timeout' || status === 429 || (typeof status === 'number' && status >= 500)

    if (!transitorio) {
      const sucesso = typeof status === 'number' && status >= 200 && status < 300
      return { tentativas, resultado: sucesso ? 'ok' : 'falha-permanente', esperas }
    }

    if (indice < maxTentativas - 1) {
      esperas.push(1000 * 2 ** indice)
    }
  }

  return { tentativas, resultado: 'esgotou', esperas }
}

