function classificarRisco(diasAtraso, valor, clienteVip) {
  if (clienteVip && diasAtraso <= 30) return 'baixo'
  if (diasAtraso > 60) return 'alto'
  if (diasAtraso > 30 || valor > 10000) return 'medio'
  return 'baixo'
}

function resumirMedicoes(medicoes) {
  const porEtapa = {}
  let total = 0

  for (const medicao of medicoes ?? []) {
    const ms = medicao?.ms
    if (!Number.isFinite(ms)) continue
    const etapa = medicao.etapa
    porEtapa[etapa] = (porEtapa[etapa] ?? 0) + ms
    total += ms
  }

  let gargalo = null
  let maior = -1
  for (const [etapa, soma] of Object.entries(porEtapa)) {
    if (soma > maior) {
      maior = soma
      gargalo = etapa
    }
  }

  return {
    total,
    porEtapa,
    gargalo,
    percentualDoGargalo: total === 0 ? 0 : Math.round((maior / total) * 100),
  }
}
